// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
    const cols = line.split(",").map(c => c.trim());
    const obj = {};
    headers.forEach((h, i) => obj[h] = cols[i] ?? "");

    // normaliza mínimo para número
    obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

    return obj;
});

return [{ json: { investimentos } }];

// Pega os dados do nó anterior (Merge)
const dados = $input.all()[0].json;

// Procura os clientes (podem estar na raiz ou dentro de 'body' vindo do webhook)
const clientes = dados.clientes || (dados.body ? dados.body.clientes : null) || [];

// Procura os investimentos
const investimentos = dados.investimentos || [];

// Se a lista de clientes estiver vazia, retorna um aviso em vez de dar erro
if (clientes.length === 0) {
  return [{ json: { erro: "Lista de clientes não encontrada. Execute o script Python novamente para enviar os dados para o Webhook." } }];
}

// Função auxiliar para escolher um item aleatório
const pick = (arr) => arr[Math.floor(Math.random() * arr.length)];

const resultados = clientes.map(c => {
  const { nome, email, perfil, saldo } = c;

  // Limpa o saldo para número (ex: "R$ 12.500,00" -> 12500)
  const saldoNum = Number(String(saldo).replace(/[^\d,-]/g, "").replace(",", "."));

  // Encontra os investimentos que combinam com o perfil do cliente
  const compativeis = investimentos.filter(inv => inv.perfil.toLowerCase() === perfil.toLowerCase());

  let escolhido = null;
  let motivo = "sem_investimento_compativel";
  let mensagens = [];

  if (compativeis.length > 0) {
    // Filtra os que o cliente tem saldo suficiente para investir
    const acessiveis = compativeis.filter(inv => saldoNum >= inv.minimo);

    if (acessiveis.length > 0) {
      escolhido = pick(acessiveis);
      motivo = "saldo_ok";

      mensagens = [
        `Olá ${nome}! Pelo seu perfil (${perfil}), uma boa opção é **${escolhido.produto}** (mínimo R$ ${escolhido.minimo.toFixed(2)}). Com seu saldo atual (${saldo}), você já consegue investir. Rentabilidade: ${escolhido.rentabilidade}.`,
        `Oi ${nome}! Recomendação para perfil ${perfil}: **${escolhido.produto}** (mínimo R$ ${escolhido.minimo.toFixed(2)}). Seu saldo (${saldo}) já atende o mínimo. Rentabilidade: ${escolhido.rentabilidade}.`,
        `${nome}, indo direto ao ponto: para o perfil ${perfil}, **${escolhido.produto}** (mínimo R$ ${escolhido.minimo.toFixed(2)}). Você tem ${saldo}, então dá pra aplicar. Rentabilidade: ${escolhido.rentabilidade}.`
      ];
    } else {
      // Se não tem saldo, recomenda o mais barato do perfil
      escolhido = compativeis.reduce((prev, curr) => (curr.minimo < prev.minimo ? curr : prev));
      motivo = "saldo_insuficiente";

      mensagens = [
        `Olá ${nome}! Seu perfil é ${perfil}. A opção mais acessível hoje é **${escolhido.produto}** (mínimo R$ ${escolhido.minimo.toFixed(2)}). Seu saldo atual é ${saldo}, então falta um pouquinho para começar. Rentabilidade: ${escolhido.rentabilidade}.`,
        `Oi ${nome}! Para o perfil ${perfil}, recomendamos **${escolhido.produto}**, mas exige R$ ${escolhido.minimo.toFixed(2)}. Com seu saldo de ${saldo}, sugerimos poupar mais um pouco!`,
      ];
    }
  } else {
    mensagens = [`Olá ${nome}! No momento não encontramos produtos específicos para o perfil ${perfil}.`];
  }

  return {
    nome,
    email,
    perfil,
    saldo_texto: saldo,
    saldo_num: saldoNum,
    recomendacao: escolhido,
    motivo,
    mensagens,
    mensagem_escolhida: pick(mensagens),
  };
});

return [{
  json: {
    ok: true,
    total_clientes: resultados.length,
    total_investimentos: investimentos.length,
    resultados
  }
}];
